<div class="detail-head"><a href="<?= url('reportes') ?>">← Volver</a><div><span class="category-pill" style="--pill:<?= e($report['color']) ?>"><?= e($report['type_name']) ?></span><h2><?= e($report['title']) ?></h2><p><?= e($report['public_code']) ?> · Reportado <?= e(date('d/m/Y H:i',strtotime($report['created_at']))) ?></p></div><span class="badge bg-<?= report_badge($report['status']) ?> badge-lg"><?= e(str_replace('_',' ',$report['status'])) ?></span></div><div class="detail-grid"><div><section class="card mb-3"><div class="card-body"><p class="report-description"><?= nl2br(e($report['description'])) ?></p><div class="info-grid"><div><small>Dirección</small><strong><?= e($report['address']?:'No indicada') ?></strong></div><div><small>Comuna / sector</small><strong><?= e($report['commune_name']) ?><?= $report['sector_name']?' · '.e($report['sector_name']):'' ?></strong></div><div><small>Prioridad</small><strong class="priority priority-<?= e($report['priority']) ?>"><?= e($report['priority']) ?></strong></div><div><small>Reportado por</small><strong><?= $report['is_anonymous']&&!can('reports.manage')?'Anónimo':e($report['reporter_name']) ?></strong></div></div><?php if($report['latitude']&&$report['longitude']):?><a class="location-box" target="_blank" rel="noopener" href="https://www.google.com/maps?q=<?= e($report['latitude']) ?>,<?= e($report['longitude']) ?>">◎ Ver ubicación: <?= e($report['latitude']) ?>, <?= e($report['longitude']) ?></a><?php endif;?></div></section><section class="card"><div class="card-header"><div><h2>Conversación y seguimiento</h2></div></div><div class="comment-list"><?php if(!$comments):?><div class="empty-state">Aún no hay comentarios.</div><?php endif;?><?php foreach($comments as $comment):?><article class="comment <?= $comment['is_internal']?'internal':'' ?>"><div class="avatar"><?= e(mb_strtoupper(mb_substr($comment['name'],0,1))) ?></div><div><strong><?= e($comment['name']) ?> <?= $comment['is_internal']?'<span class="badge bg-warning">Interno</span>':'' ?></strong><time><?= e(date('d/m/Y H:i',strtotime($comment['created_at']))) ?></time><p><?= nl2br(e($comment['body'])) ?></p></div></article><?php endforeach;?></div><form class="comment-form" method="post" action="<?= url('reportes/'.$report['id'].'/comentarios') ?>"><?= csrf_field() ?><textarea class="form-control" name="body" rows="2" required placeholder="Escribe una actualización o comentario..."></textarea><?php if(can('reports.manage')):?><label class="form-check"><input class="form-check-input" type="checkbox" name="is_internal" value="1"> Nota interna para operadores</label><?php endif;?><button class="btn btn-primary">Agregar comentario</button></form></section></div><aside>
<?php if(can('reports.manage')):?><section class="card mb-3"><div class="card-header"><div><h2>Gestionar reporte</h2></div></div><form class="card-body" method="post" action="<?= url('reportes/'.$report['id'].'/estado') ?>"><?= csrf_field() ?><div class="mb-3"><label class="form-label">Estado</label><select name="status" class="form-select"><?php foreach(['nuevo','validando','asignado','en_proceso','resuelto','cerrado','rechazado'] as $status):?><option value="<?= $status ?>" <?= $report['status']===$status?'selected':'' ?>><?= ucfirst(str_replace('_',' ',$status)) ?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Asignar a</label><select name="assigned_to" class="form-select"><option value="">Sin asignar</option><?php foreach($operators as $operator):?><option value="<?= $operator['id'] ?>" <?= (string)$report['assigned_to']===(string)$operator['id']?'selected':'' ?>><?= e($operator['name']) ?> · <?= e($operator['role_name']) ?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Nota</label><textarea name="notes" class="form-control" rows="2"></textarea></div><button class="btn btn-primary w-100">Actualizar</button></form></section><?php endif;?>
<?php if(can('reports.manage')):?><section class="card mb-3 security-profile-card"><div class="card-header"><div><h2>Ficha de seguridad</h2><p>Visible solo para personal autorizado</p></div><?= svg_icon('shield') ?></div><div class="card-body"><div><small>Persona que reporta</small><strong><?= e($report['reporter_name']) ?></strong><a href="tel:<?= e(preg_replace('/[^0-9+]/','',$report['reporter_phone'])) ?>"><?= e($report['reporter_phone']?:'Sin teléfono') ?></a></div><?php if($securityContact):?><div><small>Contacto de emergencia</small><strong><?= e($securityContact['name']) ?> · <?= e($securityContact['relationship']) ?></strong><a href="tel:<?= e(preg_replace('/[^0-9+]/','',$securityContact['phone'])) ?>"><?= e($securityContact['phone']) ?></a></div><?php else:?><p class="mb-0">Este usuario no tiene contacto de emergencia registrado.</p><?php endif;?></div></section><?php endif;?>
<?php if(can('dispatch.manage')):?><section class="card mb-3"><div class="card-header"><div><h2>Despachar servicio</h2></div></div><form class="card-body" method="post" action="<?= url('reportes/'.$report['id'].'/despachar') ?>"><?= csrf_field() ?><select name="service" class="form-select mb-2"><option value="seguridad_municipal">Seguridad municipal</option><option value="carabineros">Carabineros</option><option value="bomberos">Bomberos</option><option value="ambulancia">Ambulancia / SAMU</option><option value="transito">Tránsito</option><option value="aseo">Aseo y ornato</option><option value="alumbrado">Alumbrado público</option><option value="otro">Otro</option></select><input class="form-control mb-2" name="unit_name" placeholder="Unidad o cuadrilla"><input class="form-control mb-2" name="contact_name" placeholder="Persona de contacto"><textarea class="form-control mb-2" name="notes" placeholder="Indicaciones"></textarea><button class="btn btn-danger w-100">Registrar despacho</button></form></section><?php endif;?>
<?php if(can('dispatch.manage')&&$dispatches):?><section class="card mb-3"><div class="card-header"><div><h2>Servicios enviados</h2><p>Seguimiento operativo</p></div><a href="<?= url('despachos') ?>">Ver bandeja</a></div><div class="report-dispatch-list"><?php foreach($dispatches as $item):?><div><span><?= svg_icon('truck') ?></span><div><strong><?= e(ucfirst(str_replace('_',' ',$item['service']))) ?></strong><small><?= e($item['unit_name']?:'Sin unidad') ?> · <?= e(date('d/m H:i',strtotime($item['requested_at']))) ?></small></div><span class="badge bg-<?= dispatch_badge($item['status']) ?>"><?= e(str_replace('_',' ',$item['status'])) ?></span></div><?php endforeach;?></div></section><?php endif;?>
<section class="card"><div class="card-header"><div><h2>Historial</h2></div></div><div class="timeline"><?php foreach($history as $item):?><div><span></span><strong><?= e(ucfirst(str_replace('_',' ',$item['new_status']))) ?></strong><small><?= e($item['name']) ?> · <?= e(date('d/m H:i',strtotime($item['created_at']))) ?></small><?php if($item['notes']):?><p><?= e($item['notes']) ?></p><?php endif;?></div><?php endforeach;?></div></section></aside></div>
